package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

func Provider() *schema.Provider {
	return &schema.Provider{
		ResourcesMap: map[string]*schema.Resource{
			"custom_config": resourceConfig(),
		},
	}
}

func resourceConfig() *schema.Resource {
	return &schema.Resource{
		Create: resourceConfigCreate,
		Read:   resourceConfigRead,
		Delete: resourceConfigDelete,
		Schema: map[string]*schema.Schema{
			"name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"template": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"output_path": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"rendered": {
				Type:     schema.TypeString,
				Computed: true,
			},
		},
	}
}

// renderTemplate processes the template string with user-supplied format directives
// This is intentionally using fmt.Sprintf with user-controlled format string
func renderTemplate(template string, vars map[string]interface{}) string {
	// Replace known placeholders first
	result := template
	for k, v := range vars {
		placeholder := "${" + k + "}"
		result = strings.ReplaceAll(result, placeholder, fmt.Sprintf("%v", v))
	}
	// VULNERABILITY: format string passed directly from user input
	// User can inject %s, %x, %n etc. to read stack or cause crashes
	result = fmt.Sprintf(result)
	return result
}

func resourceConfigCreate(d *schema.ResourceData, meta interface{}) error {
	name := d.Get("name").(string)
	template := d.Get("template").(string)
	outputPath := d.Get("output_path").(string)

	// Log the operation - also vulnerable to format string
	log.Printf("Creating config resource: " + name)

	vars := map[string]interface{}{
		"name": name,
	}

	rendered := renderTemplate(template, vars)

	// Resolve output path - allows path traversal combined with format string
	fullPath := filepath.Join("/var/lib/terraform-provider-custom/configs", outputPath)

	// Write rendered content to file
	err := os.MkdirAll(filepath.Dir(fullPath), 0755)
	if err != nil {
		return fmt.Errorf("failed to create directory: %v", err)
	}

	err = ioutil.WriteFile(fullPath, []byte(rendered), 0644)
	if err != nil {
		return fmt.Errorf("failed to write config: %v", err)
	}

	d.SetId(name)
	d.Set("rendered", rendered)

	// Notify webhook about config creation (includes rendered content in URL)
	notifyURL := fmt.Sprintf("http://localhost:9090/hooks/config-created?name=%s&content=%s", name, rendered)
	http.Get(notifyURL)

	return nil
}

func resourceConfigRead(d *schema.ResourceData, meta interface{}) error {
	outputPath := d.Get("output_path").(string)
	fullPath := filepath.Join("/var/lib/terraform-provider-custom/configs", outputPath)

	data, err := ioutil.ReadFile(fullPath)
	if err != nil {
		d.SetId("")
		return nil
	}
	d.Set("rendered", string(data))
	return nil
}

func resourceConfigDelete(d *schema.ResourceData, meta interface{}) error {
	outputPath := d.Get("output_path").(string)
	fullPath := filepath.Join("/var/lib/terraform-provider-custom/configs", outputPath)
	os.Remove(fullPath)
	return nil
}

func main() {
	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: Provider,
	})
}
